 IF actual IS DISTINCT FROM $expected$["CREATE INDEX idx_produtos_ativo ON public.produtos USING btree (ativo)","CREATE INDEX idx_produtos_categoria ON public.produtos USING btree (categoria)","CREATE INDEX idx_produtos_company_id ON public.produtos USING btree (company_id)","CREATE INDEX idx_produtos_company_nome ON public.produtos USING btree (company_id, nome_produto)","CREATE INDEX idx_produtos_created_at ON public.produtos USING btree (created_at DESC)","CREATE INDEX idx_produtos_nome_unaccent_trgm ON public.produtos USING gin (nome_produto_unaccent gin_trgm_ops)","CREATE INDEX idx_produtos_sku_unaccent_trgm ON public.produtos USING gin (sku_unaccent gin_trgm_ops)","CREATE UNIQUE INDEX produtos_company_sku_unique ON public.produtos USING btree (company_id, sku) WHERE ((sku IS NOT NULL) AND (sku <> ''::text))","CREATE UNIQUE INDEX produtos_id_company_price_fk ON public.produtos USING btree (id, company_id)","CREATE UNIQUE INDEX produtos_one_active_salmon_raw ON public.produtos USING btree (company_id) WHERE (ativo AND is_salmon_raw_linked)","CREATE UNIQUE INDEX produtos_pkey ON public.produtos USING btree (id)"]$expected$::jsonb THEN RAISE EXCEPTION 'PHASE6_INDEX_DRIFT'; END IF;
 SELECT jsonb_agg(jsonb_build_array(tgname,pg_get_triggerdef(oid),tgenabled) ORDER BY tgname) FROM pg_trigger WHERE tgrelid='public.produtos'::regclass AND NOT tgisinternal INTO actual;
 IF actual IS DISTINCT FROM $expected$[["trg_aa_produtos_force_company_id","CREATE TRIGGER trg_aa_produtos_force_company_id BEFORE INSERT OR UPDATE ON public.produtos FOR EACH ROW EXECUTE FUNCTION produtos_force_company_id()","O"],["trg_audit_produtos","CREATE TRIGGER trg_audit_produtos AFTER INSERT OR DELETE OR UPDATE ON public.produtos FOR EACH ROW EXECUTE FUNCTION audit_trigger_fn('estoque', 'produtos')","O"],["trg_block_placeholder_company","CREATE TRIGGER trg_block_placeholder_company BEFORE INSERT OR UPDATE ON public.produtos FOR EACH ROW EXECUTE FUNCTION trg_block_placeholder_company()","O"]]$expected$::jsonb THEN RAISE EXCEPTION 'PHASE6_TRIGGER_DRIFT'; END IF;
 SELECT jsonb_build_object('rls',relrowsecurity,'force',relforcerowsecurity,'acl',relacl::text,'owner',pg_get_userbyid(relowner)) FROM pg_class WHERE oid='public.produtos'::regclass INTO actual;
 IF actual IS DISTINCT FROM $expected${"acl":"{postgres=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"force":true,"owner":"postgres"}$expected$::jsonb THEN RAISE EXCEPTION 'PHASE6_TABLE_ACL_DRIFT'; END IF;
 IF EXISTS(SELECT 1 FROM pg_auth_members WHERE pg_get_userbyid(member) IN ('anon','authenticated','service_role')) THEN RAISE EXCEPTION 'PHASE6_INHERITED_ROLE_DRIFT'; END IF;
 IF to_regprocedure('public.deactivate_produto(uuid)') IS NOT NULL OR EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='deactivate_produto') THEN RAISE EXCEPTION 'PHASE6_OVERLOAD_DRIFT'; END IF;
END $preflight$;

-- Policies legadas paralelas equivalentes eram OR; conservar leitura/Realtime.
DROP POLICY tenant_insert ON public.produtos;
DROP POLICY tenant_update ON public.produtos;
DROP POLICY tenant_delete ON public.produtos;
ALTER POLICY produtos_insert ON public.produtos WITH CHECK (company_id=(select public.get_current_company_id()) AND (select public.has_any_permission(auth.uid(),ARRAY['estoque:catalogo:create','estoque:cadastros:create','estoque:cadastros:manage','stock:edit','stock:write','system:global:manage'])));
ALTER POLICY produtos_update ON public.produtos USING (company_id=(select public.get_current_company_id()) AND (select public.has_any_permission(auth.uid(),ARRAY['estoque:catalogo:edit','estoque:cadastros:edit','estoque:cadastros:manage','cmv:precos:edit','stock:edit','system:global:manage']))) WITH CHECK (company_id=(select public.get_current_company_id()) AND (select public.has_any_permission(auth.uid(),ARRAY['estoque:catalogo:edit','estoque:cadastros:edit','estoque:cadastros:manage','cmv:precos:edit','stock:edit','system:global:manage'])));
-- RETURNING e UPDATE precisam de SELECT; ação permite ler o próprio recurso.
CREATE POLICY produtos_action_read ON public.produtos FOR SELECT TO authenticated USING (company_id=(select public.get_current_company_id()) AND (select public.has_any_permission(auth.uid(),ARRAY['estoque:catalogo:create','estoque:cadastros:create','estoque:cadastros:manage','stock:edit','stock:write','system:global:manage','estoque:catalogo:edit','estoque:cadastros:edit','cmv:precos:edit','estoque:catalogo:delete','estoque:cadastros:delete','stock:delete'])));
-- DELETE físico não recebe catalogo:delete. Preserva gate legado de Cadastros.
REVOKE TRUNCATE, REFERENCES, TRIGGER, MAINTAIN ON public.produtos FROM authenticated;

CREATE FUNCTION public.deactivate_produto(p_produto_id uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $fn$
DECLARE v_company uuid; v_active boolean;
BEGIN
 v_company:=public.assert_tenant();
 IF auth.uid() IS NULL OR NOT public.has_any_permission(auth.uid(),ARRAY['estoque:catalogo:delete','estoque:cadastros:delete','estoque:cadastros:manage','stock:delete','system:global:manage']) THEN RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE='42501'; END IF;
 SELECT ativo INTO v_active FROM public.produtos WHERE id=p_produto_id AND company_id=v_company FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PRODUCT_NOT_FOUND' USING ERRCODE='42501'; END IF;
 IF v_active THEN UPDATE public.produtos SET ativo=false WHERE id=p_produto_id AND company_id=v_company; END IF;
 RETURN p_produto_id;
END $fn$;
REVOKE ALL ON FUNCTION public.deactivate_produto(uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.deactivate_produto(uuid) TO authenticated;

-- Não normalizar silenciosamente empresa arbitrária para a empresa corrente.
CREATE OR REPLACE FUNCTION public.produtos_force_company_id() RETURNS trigger
LANGUAGE plpgsql SET search_path='' AS $fn$
DECLARE v_company uuid;
BEGIN
 IF TG_OP='INSERT' THEN
  v_company:=public.assert_tenant();
  IF NEW.company_id IS DISTINCT FROM v_company THEN RAISE EXCEPTION 'PRODUCT_COMPANY_MISMATCH' USING ERRCODE='42501'; END IF;
 ELSIF TG_OP='UPDATE' THEN
  IF NEW.company_id IS DISTINCT FROM OLD.company_id THEN RAISE EXCEPTION 'PRODUCT_COMPANY_IMMUTABLE' USING ERRCODE='42501'; END IF;
  IF current_user='authenticated' AND NEW.ativo IS DISTINCT FROM OLD.ativo AND NEW.ativo IS NOT TRUE THEN
   RAISE EXCEPTION 'USE_DEACTIVATE_PRODUTO' USING ERRCODE='42501';
  END IF;
 END IF;
 RETURN NEW;
END $fn$;
REVOKE ALL ON FUNCTION public.produtos_force_company_id() FROM PUBLIC, anon, authenticated, service_role;

-- Helper de custo sem guard e sem caller externo legítimo: só chamada interna.
REVOKE ALL ON FUNCTION public.recalc_product_costs(uuid) FROM PUBLIC, anon, authenticated, service_role;
CREATE OR REPLACE FUNCTION public.generate_next_sku(p_prefix text DEFAULT 'MP'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company_id uuid;
  v_next bigint;
  v_pad integer;
  v_candidate text;
  v_attempts integer := 0;
  v_max_attempts integer := 1000;
BEGIN
  v_company_id := public.assert_tenant();
  -- Salmão cria seu produto internamente; mantém caller/corpo/lock da Fase 4.
  IF auth.uid() IS NULL OR NOT (public.has_any_permission(auth.uid(),ARRAY['estoque:catalogo:create','estoque:cadastros:create','estoque:cadastros:manage','stock:edit','stock:write','system:global:manage']) OR (p_prefix='SALM' AND public.has_any_permission(auth.uid(),ARRAY['salmon:entradas:create','salmon:entries:create','salmon:write','system:global:manage']))) THEN RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE='42501'; END IF;
  IF p_prefix IS NULL OR length(p_prefix) NOT BETWEEN 1 AND 32 THEN RAISE EXCEPTION 'INVALID_SKU_PREFIX' USING ERRCODE='22023'; END IF;

  INSERT INTO public.stock_sku_counter (company_id, prefix, next_value, pad_length, updated_at)
  VALUES (v_company_id, p_prefix, 0, 4, now())
  ON CONFLICT (company_id, prefix) DO NOTHING;

  LOOP
    v_attempts := v_attempts + 1;
    IF v_attempts > v_max_attempts THEN
      RAISE EXCEPTION
        'generate_next_sku: nao foi possivel gerar SKU unico apos % tentativas (company=%, prefix=%)',
        v_max_attempts, v_company_id, p_prefix;
    END IF;

    UPDATE public.stock_sku_counter
       SET next_value = next_value + 1,
           updated_at = now()
     WHERE company_id = v_company_id
       AND prefix = p_prefix
    RETURNING next_value, pad_length INTO v_next, v_pad;

    v_candidate := p_prefix || '-' || lpad(v_next::text, GREATEST(COALESCE(v_pad, 4), 1), '0');

    IF NOT EXISTS (
      SELECT 1
      FROM public.produtos
      WHERE company_id = v_company_id
        AND sku = v_candidate
    ) THEN
      RETURN v_candidate;
    END IF;
  END LOOP;
END;
$function$
;
REVOKE ALL ON FUNCTION public.generate_next_sku(text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.generate_next_sku(text) TO authenticated;
NOTIFY pgrst, 'reload schema';
COMMIT;
